-- Exact student and correction scope; no changes to recruitment history.
CREATE ROLE nexustalent_academic_writer NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB;
GRANT USAGE ON SCHEMA nexustalent TO nexustalent_academic_writer;
GRANT SELECT, INSERT, UPDATE ON nexustalent.records TO nexustalent_academic_writer;
GRANT EXECUTE ON FUNCTION nexustalent.actor_role() TO nexustalent_academic_writer;
CREATE POLICY academic_read ON nexustalent.records FOR SELECT TO nexustalent_academic_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.academic_action',true) IN ('REQUEST_ACADEMIC_CORRECTION','REVIEW_ACADEMIC_CORRECTION') AND document_path NOT LIKE '%/%/%' AND ((collection='users' AND document_path='users/'||current_setting('nexustalent.actor_uid',true)) OR (collection='students' AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR payload->>'institutionId'=current_setting('nexustalent.actor_uid',true))))) OR (collection='academicCorrections' AND document_path='academicCorrections/'||(CASE WHEN current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' THEN encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') ELSE current_setting('nexustalent.correction_id',true) END) AND payload->>'studentId'=current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR payload->>'institutionId'=current_setting('nexustalent.actor_uid',true)))))
 OR (((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION') AND collection='institutions' AND document_path='institutions/'||current_setting('nexustalent.actor_uid',true))
 OR ((((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR (current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION')))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'action'=current_setting('nexustalent.academic_action',true))));
CREATE POLICY academic_insert ON nexustalent.records FOR INSERT TO nexustalent_academic_writer WITH CHECK (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.academic_action',true) IN ('REQUEST_ACADEMIC_CORRECTION','REVIEW_ACADEMIC_CORRECTION') AND document_path NOT LIKE '%/%/%' AND (( ((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) AND (collection='academicCorrections' AND document_path='academicCorrections/'||(CASE WHEN current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' THEN encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') ELSE current_setting('nexustalent.correction_id',true) END) AND payload->>'studentId'=current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR payload->>'institutionId'=current_setting('nexustalent.actor_uid',true))))) AND payload->>'id'=split_part(document_path,'/',2) AND payload->>'status'='pending'
 AND payload-ARRAY['id','studentId','institutionId','status','before','proposed','reason','requestedAt']='{}'::jsonb)
 OR ((((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR (current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION')))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex')
 AND payload->>'eventId'=split_part(document_path,'/',2) AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'actorRole'=(SELECT nexustalent.actor_role())
 AND payload->>'requestId'=current_setting('nexustalent.request_id',true) AND payload->>'action'=current_setting('nexustalent.academic_action',true) AND payload->'immutable'='true'::jsonb
 AND payload->'ids'=jsonb_build_array(CASE WHEN current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' THEN encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') ELSE current_setting('nexustalent.correction_id',true) END,current_setting('nexustalent.target_id',true)))));
CREATE POLICY academic_update ON nexustalent.records FOR UPDATE TO nexustalent_academic_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.academic_action',true) IN ('REQUEST_ACADEMIC_CORRECTION','REVIEW_ACADEMIC_CORRECTION') AND document_path NOT LIKE '%/%/%' AND payload->>'id'=split_part(document_path,'/',2) AND ((collection='students' AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR payload->>'institutionId'=current_setting('nexustalent.actor_uid',true))))) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (collection='academicCorrections' AND document_path='academicCorrections/'||(CASE WHEN current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' THEN encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') ELSE current_setting('nexustalent.correction_id',true) END) AND payload->>'studentId'=current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' AND current_setting('nexustalent.target_id',true)=current_setting('nexustalent.actor_uid',true)) OR ((current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.academic_action',true)='REVIEW_ACADEMIC_CORRECTION'))) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR payload->>'institutionId'=current_setting('nexustalent.actor_uid',true))))))));
CREATE FUNCTION nexustalent.guard_academic_write() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a text:=current_setting('nexustalent.academic_action',true); correction jsonb; st jsonb; expected jsonb; k text; v jsonb; grants jsonb; creds jsonb; reviewed text;
BEGIN
 IF NOT pg_has_role(current_user,'nexustalent_academic_writer','MEMBER') OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF split_part(NEW.document_path,'/',1)='auditEvents' THEN RETURN NEW; END IF;
  IF split_part(NEW.document_path,'/',1)<>'academicCorrections' OR a<>'REQUEST_ACADEMIC_CORRECTION' THEN RAISE EXCEPTION 'Invalid correction insert' USING ERRCODE='23514'; END IF;
  SELECT payload INTO st FROM nexustalent.records WHERE document_path='students/'||current_setting('nexustalent.target_id',true);
  correction:=NEW.payload;
  IF st IS NULL OR st->'academicCorrection'->>'status'='pending' OR correction->>'institutionId' IS DISTINCT FROM COALESCE(st->>'institutionId','')
   OR length(trim(COALESCE(correction->>'reason',''))) NOT BETWEEN 1 AND 1000 OR COALESCE(correction->>'requestedAt','')=''
   OR jsonb_typeof(correction->'proposed') IS DISTINCT FROM 'object' OR jsonb_typeof(correction->'before') IS DISTINCT FROM 'object'
   OR correction->'proposed'='{}'::jsonb OR ARRAY(SELECT jsonb_object_keys(correction->'proposed') ORDER BY 1) IS DISTINCT FROM ARRAY(SELECT jsonb_object_keys(correction->'before') ORDER BY 1)
  THEN RAISE EXCEPTION 'Invalid correction request' USING ERRCODE='23514'; END IF;
  FOR k,v IN SELECT key,value FROM jsonb_each(correction->'proposed') LOOP
   IF k NOT IN ('program','branch','graduationYear','cgpa','rollNumber') OR correction->'before'->k IS DISTINCT FROM COALESCE(st->k,'null'::jsonb) OR v IS NOT DISTINCT FROM COALESCE(st->k,'null'::jsonb) THEN RAISE EXCEPTION 'Invalid correction field' USING ERRCODE='23514'; END IF;
   IF k='graduationYear' THEN
    IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR (v#>>'{}')::numeric NOT BETWEEN 1950 AND 2100 OR trunc((v#>>'{}')::numeric)<>(v#>>'{}')::numeric THEN RAISE EXCEPTION 'Invalid graduation year' USING ERRCODE='23514'; END IF;
   ELSIF k='cgpa' THEN
    IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR (v#>>'{}')::numeric NOT BETWEEN 0 AND 10 THEN RAISE EXCEPTION 'Invalid CGPA' USING ERRCODE='23514'; END IF;
   ELSIF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(trim(v#>>'{}')) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Invalid academic text' USING ERRCODE='23514'; END IF;
  END LOOP;
  RETURN NEW;
 END IF;
 IF a='REVIEW_ACADEMIC_CORRECTION' AND (SELECT nexustalent.actor_role())='institution' AND NOT EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='institutions/'||current_setting('nexustalent.actor_uid',true) AND payload->>'empanelmentStatus'='empanelled') THEN RAISE EXCEPTION 'Empanelled authority required' USING ERRCODE='23514'; END IF;
 IF OLD.collection='academicCorrections' AND a='REVIEW_ACADEMIC_CORRECTION' THEN
  SELECT payload INTO st FROM nexustalent.records WHERE document_path='students/'||current_setting('nexustalent.target_id',true);
  IF st IS NULL OR st->'academicCorrection'->>'id' IS DISTINCT FROM OLD.payload->>'id' OR OLD.payload->>'status' IS DISTINCT FROM 'pending'
   OR COALESCE(NEW.payload->>'status','') NOT IN ('approved','rejected') OR NEW.payload->>'reviewedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true)
   OR COALESCE(NEW.payload->>'reviewedAt','')='' OR length(trim(COALESCE(NEW.payload->>'reviewNote',''))) NOT BETWEEN 1 AND 1000
   OR (NEW.payload-ARRAY['status','reviewNote','reviewedBy','reviewedAt']) IS DISTINCT FROM (OLD.payload-ARRAY['status','reviewNote','reviewedBy','reviewedAt'])
  THEN RAISE EXCEPTION 'Invalid correction review' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 ELSIF OLD.collection='students' THEN
  SELECT payload INTO correction FROM nexustalent.records WHERE document_path='academicCorrections/'||(CASE WHEN current_setting('nexustalent.academic_action',true)='REQUEST_ACADEMIC_CORRECTION' THEN encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.academic_action',true),'UTF8')),'hex') ELSE current_setting('nexustalent.correction_id',true) END);
  IF correction IS NULL OR correction->>'studentId' IS DISTINCT FROM current_setting('nexustalent.target_id',true) THEN RAISE EXCEPTION 'Missing bound correction' USING ERRCODE='23514'; END IF;
  expected:=OLD.payload||jsonb_build_object('academicCorrection',correction);
  IF a='REQUEST_ACADEMIC_CORRECTION' THEN
   IF correction->>'status' IS DISTINCT FROM 'pending' OR OLD.payload->'academicCorrection'->>'status'='pending' THEN RAISE EXCEPTION 'Pending correction required' USING ERRCODE='23514'; END IF;
  ELSIF a='REVIEW_ACADEMIC_CORRECTION' THEN
   IF OLD.payload->'academicCorrection'->>'id' IS DISTINCT FROM correction->>'id' OR OLD.payload->'academicCorrection'->>'status' IS DISTINCT FROM 'pending' OR correction->>'reviewedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true) OR COALESCE(correction->>'status','') NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Review binding mismatch' USING ERRCODE='23514'; END IF;
   IF correction->>'status'='approved' THEN
    IF jsonb_typeof(correction->'proposed') IS DISTINCT FROM 'object' OR correction->'proposed'='{}'::jsonb OR jsonb_typeof(correction->'before') IS DISTINCT FROM 'object'
     OR ARRAY(SELECT jsonb_object_keys(correction->'proposed') ORDER BY 1) IS DISTINCT FROM ARRAY(SELECT jsonb_object_keys(correction->'before') ORDER BY 1) THEN RAISE EXCEPTION 'Invalid historical correction' USING ERRCODE='23514'; END IF;
    FOR k,v IN SELECT key,value FROM jsonb_each(correction->'proposed') LOOP
     IF k NOT IN ('program','branch','graduationYear','cgpa','rollNumber') OR COALESCE(OLD.payload->k,'null'::jsonb) IS DISTINCT FROM correction->'before'->k THEN RAISE EXCEPTION 'Stale or invalid correction' USING ERRCODE='23514'; END IF;
     IF k='graduationYear' THEN IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR (v#>>'{}')::numeric NOT BETWEEN 1950 AND 2100 OR trunc((v#>>'{}')::numeric)<>(v#>>'{}')::numeric THEN RAISE EXCEPTION 'Invalid graduation year' USING ERRCODE='23514'; END IF;
     ELSIF k='cgpa' THEN IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR (v#>>'{}')::numeric NOT BETWEEN 0 AND 10 THEN RAISE EXCEPTION 'Invalid CGPA' USING ERRCODE='23514'; END IF;
     ELSIF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(trim(v#>>'{}')) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Invalid academic text' USING ERRCODE='23514'; END IF;
    END LOOP;
    reviewed:=correction->>'reviewedAt';
    SELECT COALESCE(jsonb_object_agg(key,value||jsonb_build_object('status','denied','academicDataShared',false,'skillBenchmarksShared',false,'projectReposShared',false,'contactInfoShared',false,'updatedAt',reviewed,'reasonForDenial','Academic profile corrected; fresh consent required')),'{}'::jsonb) INTO grants FROM jsonb_each(COALESCE(OLD.payload->'campaignConsents','{}'::jsonb));
    expected:=expected||(correction->'proposed')||jsonb_build_object('academicCorrectedAt',reviewed,'institutionVerificationStatus',CASE WHEN OLD.payload->>'institutionVerificationStatus'='not_applicable' THEN 'not_applicable' ELSE 'pending' END,'platformVerificationStatus','pending','verificationNotes','Academic correction reviewed; fresh verification required.','campaignConsents',grants);
    IF jsonb_typeof(OLD.payload->'independentCredentials')='object' THEN
     creds:=OLD.payload->'independentCredentials';
     FOR k,v IN SELECT key,value FROM jsonb_each(correction->'proposed') LOOP creds:=creds||jsonb_build_object(CASE WHEN k='program' THEN 'degree' ELSE k END,v); END LOOP;
     expected:=expected||jsonb_build_object('independentCredentials',creds);
    END IF;
   END IF;
  ELSE RAISE EXCEPTION 'Invalid correction action' USING ERRCODE='23514'; END IF;
  IF NEW.payload IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Academic correction must match reviewed fields and revoke consent' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Unrelated academic mutation' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END
$$;
CREATE TRIGGER academic_write_guard BEFORE INSERT OR UPDATE ON nexustalent.records FOR EACH ROW EXECUTE FUNCTION nexustalent.guard_academic_write();
REVOKE ALL ON FUNCTION nexustalent.guard_academic_write() FROM PUBLIC;
